import{z as d,x as m,o as s,c as p,q as i,j as l,D as r,d as t,s as o,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"数组与随机访问","description":"","frontmatter":{"title":"数组与随机访问","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/array-random-access.md","filePath":"cs/array-random-access.md","lastUpdated":1791063341000}'),E={name:"cs/array-random-access.md"};function h(c,a,B,D,T,u){const n=m("Mermaid");return s(),p("div",null,[a[2]||(a[2]=i('<h1 id="数组与随机访问" tabindex="-1">数组与随机访问 <a class="header-anchor" href="#数组与随机访问" aria-label="Permalink to &quot;数组与随机访问&quot;">​</a></h1><div class="epigraph"><p>下标到地址是一次乘加；RAM 模型里那是 $O(1)$，前提是元素连续且大小已知。</p><footer>—— 据 Knuth, The Art of Computer Programming 卷 1；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/adt-cost">上一课</a>把结构写成操作加代价，还没有任何一种布局。<a href="/cs/bit-as-distinction">比特作为区分</a>与<a href="/cs/adt-cost">进制与位权</a>已经能把下标写成整数。<a href="/cs/memory-array-sram-dram">SRAM 与 DRAM 阵列</a>按地址读字。<a href="/cs/calling-convention-stack">调用约定与栈</a>里的栈槽其实已经是数组片段。本课不重讲 ADT 合同。缺口是第一种表示：连续元素 + 按下标 \\(O(1)\\) 取。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>集合的「第 \\(i\\) 个」若每次从头数，代价随 \\(i\\) 涨。硬件却已经提供按物理地址的常数时间字访问（cache 命中时）。缺口是把 ADT 的下标映射到地址：\\(\\mathrm{addr}(A[i]) = \\mathrm{base} + i \\times \\mathrm{size}\\)。本课只钉静态长度或长度存在另处的定长数组，不讨论自动扩容——那是摊还课。</p><p>插入到中间要搬移后续元素，最坏 \\(\\Theta(n)\\)。合同必须把「按下标读」和「在中间插入」分开写，不能都叫 \\(O(1)\\)。</p><p><span class="marginnote">RAM 模型假定任意字地址 \\(O(1)\\)。层次存储器下这是命中时的近似；行对齐的顺序扫才吃满空间局部性。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>表示：一块连续虚拟地址，元素同宽。读写下标 \\(i\\) 合法当且仅当 \\(0\\le i\\lt n\\)。构造分配 \\(n\\times\\mathrm{size}\\) 字节。随机访问 \\(\\Theta(1)\\) 步；顺序扫 \\(\\Theta(n)\\) 步且对 cache 友好。</p><p><span class="marginnote">把地址公式代入具体数：基址取 0x1000、每个元素 8 字节时，\\(A[5]\\) 的地址就是 \\(0\\mathrm{x}1000 + 5\\times 8 = 0\\mathrm{x}1028\\)，一次乘加直达，完全不用从 \\(A[0]\\) 数过去——这就是「随机」两个字的含义：访问第几个都一样快。</span></p>',10)),(s(),l(A,null,{default:r(()=>[o(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20LR%0A%20%20I%5B%22%E4%B8%8B%E6%A0%87%20i%22%5D%20--%3E%20MUL%5B%22i%20%C3%97%20%E5%85%83%E7%B4%A0%E5%A4%A7%E5%B0%8F%22%5D%0A%20%20MUL%20--%3E%20ADD%5B%22%E5%8A%A0%E5%9F%BA%E5%9D%80%22%5D%0A%20%20ADD%20--%3E%20LD%5B%22%E4%B8%80%E6%AC%A1%20load%2Fstore%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[t("多维数组按行主序或列主序展开成一维；跨大步长会打穿"),e("a",{href:"/cs/locality-principle"},"局部性原理"),t("，渐近步数仍 \\(\\Theta(1)\\) 每次访问。这正是合同里「步」与「常数」要分开的理由。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"数组把字典里「已知下标」这一特例做到最优。未知键的查找仍要扫，无序时 \\(\\Theta(n)\\)。后课链表用指针换「中间插入 \\(\\Theta(1)\\)」（已有前驱时），代价是丢掉随机访问和局部性。",-1)),a[6]||(a[6]=e("p",null,"同一个「在位置 2 插入 \\(x\\)」，两种结构付出的代价完全不同：",-1)),(s(),l(A,null,{default:r(()=>[o(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20ARR%5B%22%E6%95%B0%E7%BB%84%22%5D%0A%20%20%20%20A1%5B%22%E4%BD%8D%E7%BD%AE%202%20%E5%8F%8A%E4%B9%8B%E5%90%8E%E5%85%A8%E9%83%A8%E5%8F%B3%E7%A7%BB%E4%B8%80%E6%A0%BC%22%5D%20--%3E%20A2%5B%22%E7%A9%BA%E5%87%BA%E7%9A%84%E4%BD%8D%E7%BD%AE%202%20%E5%86%99%E5%85%A5%20x%22%5D%0A%20%20end%0A%20%20subgraph%20LST%5B%22%E9%93%BE%E8%A1%A8%22%5D%0A%20%20%20%20B1%5B%22%E6%96%B0%E8%8A%82%E7%82%B9%20x%20%E7%9A%84%20next%20%E6%8C%87%E5%90%91%E5%90%8E%E7%BB%A7%22%5D%20--%3E%20B2%5B%22%E5%89%8D%E9%A9%B1%E7%9A%84%20next%20%E6%94%B9%E6%8C%87%20x%22%5D%0A%20%20end%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">直觉类比：数组像一排编号连续的储物柜，报出编号直接走到对应柜子；链表像寻宝游戏，每个盒子里只藏着下一个盒子的位置——想拿第 100 件东西就得挨个开 100 次盒子。</span></p><p><span class="marginnote">常见误区：初学者容易以为「随机访问 \\(\\Theta(1)\\)」等于「数组干什么都是 \\(\\Theta(1)\\)」。实际上在中间插入或删除一个元素要搬动后面所有元素，\\(n\\) 很大时这一步才是开销大头；测性能时别只测按下标读写。</span></p><p>边界检查不是 ISA 默认：越界是安全课才会强制的，本课在合同里写前置条件，实现可以省略检查。定长构造失败只发生在分配阶段，不发生在下标算术里。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入动态数组的倍增，不把切片当成独立 ADT。也不把数组写成「唯一的表」：关联查找是树与散列的缺口。NUMA 上大数组可能跨节点，地址计算仍是乘加，延迟不是 \\(O(1)\\) 纳秒。</p><p>后课默认：谈到连续表，按下标读写 \\(\\Theta(1)\\) 步；中间插入需搬移。链表用来买另一组代价。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>连续布局把下标变成基址加偏移，RAM 下随机访问 \\(\\Theta(1)\\)。</li><li>中间插入 \\(\\Theta(n)\\)；顺序扫吃空间局部性。</li><li>链表用指针换插入，下一课把局部性代价说清。</li><li>倍增扩容不在本课；按下标仍假定长度已知。</li><li>出处：Knuth, <em>TAOCP</em> 卷 1；Cormen et al. 数组作为表的表示。</li></ul>',8))])}const x=d(E,[["render",h]]);export{_ as __pageData,x as default};
